SELECT *, COUNT(temp_c) OVER w_running AS device_code_count_temp_c, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY humidity DESC) AS humidity_dense_rank, FIRST_VALUE(humidity) IGNORE NULLS OVER w_recent AS first_known_humidity, LEAD(temp_c, 1) OVER (ORDER BY status_bits, id) AS next_temp_c, DENSE_RANK() OVER (PARTITION BY device_code ORDER BY temp_c NULLS LAST) AS temp_c_dense_rank FROM device_readings WINDOW w_running AS (PARTITION BY device_code), w_recent AS (PARTITION BY device_code ORDER BY humidity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
